def split_before(iterable, pred, maxsplit=-1):
    if maxsplit == 0:
        yield list(iterable)
        return

    buf = []
    it = iter(iterable)
    try:
        first_item = next(it)
    except StopIteration:
        if buf:
            yield buf
        return

    if pred(first_item):
        if maxsplit == -1 or maxsplit == 0:
            yield [first_item]
            buf = []
        else:
            yield [first_item]
            maxsplit -= 1
            buf = []
    else:
        buf.append(first_item)

    for item in it:
        if pred(item) and buf:
            yield buf
            if maxsplit == 1:
                yield [item, *it]
                return
            buf = []
            maxsplit -= 1
        buf.append(item)
    if buf:
        yield buf
```

